-- Delivery zones become the real map of Libya.
--
-- Until now a "zone" was one of the 22 shabiyat — an administrative region the
-- size of a province. Nobody delivers to a province. This replaces that content
-- with 407 actual neighbourhoods carrying the four levels the business works in:
--
--   المدينة الكبرى ← النطاق الجغرافي ← المنطقة / الحي ← البلدية
--
-- The TABLE is not renamed and no relationship changes. `orders.zone_id`,
-- `sales_reps.zones`, `order_commission`, `store_zones` and the spreadsheet
-- importer all keep working exactly as they did — a zone is simply a smaller,
-- truer thing now. Renaming the concept across the codebase would have been a
-- 25-file rewrite of working money paths to change a noun.
--
-- Safe to replace the rows outright: nothing referenced them. At the time of
-- writing there were 0 store copies, 0 orders carrying a zone_id, and 0 reps
-- with zone coverage — verified before this was written, and asserted below so
-- the migration refuses rather than orphaning anything if that is untrue.
--
-- Sources: OpenStreetMap (every area row carries the element id it came from)
-- and the Ministry of Local Government municipality list. See docs/libya-areas.md
-- for coverage gaps — Al Khums, Zuwara and Sabratha have no mapped
-- neighbourhoods yet, while Derna has only one; these need adding by hand.

-- ------------------------------------------------------ the four levels
alter table public.delivery_zones add column if not exists city text not null default '';
alter table public.delivery_zones add column if not exists scope text not null default '';
alter table public.delivery_zones add column if not exists municipality text not null default '';
alter table public.delivery_zones add column if not exists alt_name text not null default '';
alter table public.delivery_zones add column if not exists lat numeric(9, 6);
alter table public.delivery_zones add column if not exists lon numeric(9, 6);
/** True where OpenStreetMap holds only a Latin name; an Arabic one is wanted. */
alter table public.delivery_zones add column if not exists needs_translation boolean not null default false;
/** The OSM element this row came from, so any name can be traced or rechecked. */
alter table public.delivery_zones add column if not exists source text not null default '';

create index if not exists delivery_zones_city_idx on public.delivery_zones (city);
create index if not exists delivery_zones_scope_idx on public.delivery_zones (city, scope);
create index if not exists delivery_zones_municipality_idx on public.delivery_zones (municipality);

-- ------------------------------------------------------- the municipalities
--
-- Reference only: 140 baladiyat, 101 of which have no mapped area currently. Kept as
-- its own table so the level-4 list stays complete even where no neighbourhood
-- has been mapped into it yet.
create table if not exists public.municipalities (
  id text primary key default gen_random_uuid()::text,
  name text not null unique,
  lat numeric(9, 6),
  lon numeric(9, 6)
);

alter table public.municipalities enable row level security;

drop policy if exists "Active users can read municipalities" on public.municipalities;
create policy "Active users can read municipalities"
  on public.municipalities for select to authenticated
  using ((select public.is_active_user()));

drop policy if exists "Admins can manage municipalities" on public.municipalities;
create policy "Admins can manage municipalities"
  on public.municipalities for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));

revoke all on public.municipalities from anon, authenticated;
grant select on public.municipalities to authenticated;
grant insert, update, delete on public.municipalities to authenticated;

-- --------------------------------------------------- refuse to orphan anything
do $$
declare
  v_refs bigint;
begin
  select (select count(*) from public.orders where zone_id is not null)
       + (select count(*) from public.delivery_zones where store_id is not null)
       + (select count(*) from public.sales_reps where cardinality(zones) > 0)
    into v_refs;
  if v_refs > 0 then
    raise exception
      'ZONES_IN_USE: % references exist. Replacing the shabiyat would orphan them; migrate first.', v_refs;
  end if;
end;
$$;

-- The 22 shabiyat go, and the new rows come in numbered from 000.
--
-- Both triggers come off for the load and go back on after:
--   * the permission check asks whether the current user may create a zone in a
--     store, and a migration has no user and no store -- these rows are the
--     shared catalogue every store reads;
--   * the audit trigger would write 407 rows saying "the schema loaded its own
--     reference data", which is noise in a log meant for who changed what.
alter table public.delivery_zones disable trigger enforce_delivery_zones_permissions;
alter table public.delivery_zones disable trigger audit_delivery_zones;

delete from public.delivery_zones;
alter sequence public.delivery_zone_code_seq restart with 0;

